// @ts-nocheck
// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate, spring } from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadInter = makeLoadFont('Inter');

// Library: none — native interpolate/spring for counter and layout animation

const { fontFamily: interFamily } = loadInter();



export type PointsCounterProps = Record<string, any>;

const SWATCH_COLORS = [
  "#7B2CBF", // Purple (Active)
  "#007AFF", // Blue
  "#00C7BE", // Cyan
  "#34C759", // Green
  "#FFCC00", // Yellow
  "#FF9500", // Orange
  "#FF2D55", // Pink
  "#E3000F", // Red
];

const PointsCounter: React.FC<PointsCounterProps> = ({
  backgroundColor = "#1a1a1a",
  transparentBackground = false,
  durationInSeconds = 6,
  targetPoints = 200000,
  pointsColor = "#7B2CBF",
  brandColor = "#E3000F",
  label = "Qantas Points",
  bottomText = "CUSTOMISABLE POINTS COLOUR",
  showSwatches = true,
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();
  const s = Math.min(width, height) / 1080;

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Timings
  const circleEntranceStart = 5;
  const boxEntranceStart = 15;
  const counterStart = 25;
  const swatchesStart = 60;

  // Animations
  const circleScale = spring({
    frame: frame - circleEntranceStart,
    fps,
    config: { damping: 14, mass: 1.2 },
  });

  const boxOpacity = interpolate(frame, [boxEntranceStart, boxEntranceStart + 15], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  
  const boxTranslateY = spring({
    frame: frame - boxEntranceStart,
    fps,
    config: { damping: 12 },
  });

  // Smooth deceleration for the counter
  const counterProgress = spring({
    frame: frame - counterStart,
    fps,
    config: { damping: 20, mass: 3, stiffness: 60 },
  });

  const currentPoints = Math.floor(interpolate(counterProgress, [0, 1], [0, targetPoints], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  }));

  const formattedPoints = new Intl.NumberFormat('en-US').format(currentPoints);

  const swatchesOpacity = interpolate(frame, [swatchesStart, swatchesStart + 20], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  const swatchesTranslateY = interpolate(frame, [swatchesStart, swatchesStart + 20], [40 * s, 0], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, fontFamily: interFamily, alignItems: "center", justifyContent: "center" }}>
      
      {/* Main Graphic Container */}
      <div 
        style={{ 
          position: "relative", 
          width: 760 * s, 
          height: 760 * s,
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          transform: `scale(${circleScale})`,
          opacity: frame >= circleEntranceStart ? 1 : 0,
          transition: "none"
        }}
      >
        {/* The White Circle with Red Border */}
        <div
          style={{
            position: "absolute",
            inset: 0,
            backgroundColor: "#ffffff",
            borderRadius: "50%",
            border: `${24 * s}px solid ${brandColor}`,
            display: "flex",
            flexDirection: "column",
            alignItems: "center",
            justifyContent: "center",
            boxSizing: "border-box",
            paddingTop: 40 * s, // offset for the box at the top
            boxShadow: `0 ${10 * s}px ${30 * s}px rgba(0,0,0,0.3)`,
            transition: "none"
          }}
        >
          <div 
            style={{ 
              color: pointsColor, 
              fontSize: 160 * s, 
              fontWeight: 800,
              lineHeight: 1,
              letterSpacing: `-${2 * s}px`,
              transition: "none"
            }}
          >
            {formattedPoints}
          </div>
          <div 
            style={{ 
              color: "#333333", 
              fontSize: 64 * s, 
              fontWeight: 500,
              marginTop: 16 * s,
              transition: "none"
            }}
          >
            {label}
          </div>
        </div>

        {/* The Red Logo Box Container */}
        <div
          style={{
            position: "absolute",
            top: -50 * s,
            left: "50%",
            width: 320 * s,
            height: 180 * s,
            marginLeft: -160 * s, // half width
            backgroundColor: brandColor,
            borderRadius: 16 * s,
            display: "flex",
            alignItems: "center",
            justifyContent: "center",
            opacity: boxOpacity,
            transform: `translateY(${(1 - boxTranslateY) * (-40 * s)}px)`,
            boxShadow: `0 ${8 * s}px ${20 * s}px rgba(0,0,0,0.2)`,
            transition: "none"
          }}
        >
          {/* Abstract Swoosh to represent the logo space */}
          <svg width={140 * s} height={80 * s} viewBox="0 0 140 80" style={{ transition: "none" }}>
            <path 
              d="M 20 70 C 50 60, 60 50, 70 30 C 80 15, 95 10, 110 15 C 95 35, 75 60, 30 75 Z" 
              fill="#ffffff" 
              style={{ transition: "none" }}
            />
          </svg>
        </div>
      </div>

      {/* Optional Swatches UI at the bottom */}
      {showSwatches && (
        <div
          style={{
            position: "absolute",
            bottom: 80 * s,
            display: "flex",
            flexDirection: "column",
            alignItems: "center",
            opacity: swatchesOpacity,
            transform: `translateY(${swatchesTranslateY}px)`,
            transition: "none"
          }}
        >
          <div style={{ display: "flex", gap: 32 * s, marginBottom: 32 * s, transition: "none" }}>
            {SWATCH_COLORS.map((color, i) => {
              const isActive = color.toUpperCase() === pointsColor.toUpperCase();
              return (
                <div
                  key={i}
                  style={{
                    width: 56 * s,
                    height: 56 * s,
                    borderRadius: "50%",
                    backgroundColor: color,
                    border: isActive ? `${4 * s}px solid #ffffff` : "none",
                    boxShadow: isActive ? `0 0 0 ${2 * s}px ${color}` : "none",
                    transition: "none"
                  }}
                />
              );
            })}
          </div>
          <div
            style={{
              color: "#ffffff",
              fontSize: 24 * s,
              fontWeight: 600,
              letterSpacing: 2 * s,
              opacity: 0.8,
              transition: "none"
            }}
          >
            {bottomText}
          </div>
        </div>
      )}

    </AbsoluteFill>
  );
};

export default PointsCounter;